@Override
public List<Error> validateRiskDetails(RiskMasterSaveReq req) {

	List<Error> errorList = new ArrayList<Error>();

	try {
	
		if (StringUtils.isBlank(req.getRiskName()) || req.getRiskName() == null) {
			errorList.add(new Error("02", "RiskName", "Please Select Risk  Name "));
		}else if (req.getRiskName().length() > 100){
			errorList.add(new Error("02","RiskName", "Please Enter Risk  Name within 100 Characters")); 
		}else if (StringUtils.isBlank(req.getRiskId().toString())) {
			Long RiskCount = repo.countByRiskNameOrderByEntryDateDesc(req.getRiskName());
			if (RiskCount > 0 ) {
				errorList.add(new Error("01", "Risk", "This Risk Alrady Exist "));
			}
		}

		if (StringUtils.isBlank(req.getProductId()) || req.getProductId() == null) {
			errorList.add(new Error("03", "ProductId", "Please Enter Product Id "));
		}
		// Date Validation 
		Calendar cal = new GregorianCalendar();
		Date today = new Date();
		cal.setTime(today);cal.add(Calendar.DAY_OF_MONTH, -1);cal.set(Calendar.HOUR_OF_DAY, 23);cal.set(Calendar.MINUTE, 50);
		today = cal.getTime();
		if (req.getEffectiveDate() == null || StringUtils.isBlank(req.getEffectiveDate().toString())) {
			errorList.add(new Error("04", "EffectiveDateStart", "Please Enter Effective Date Start"));

		} else if (req.getEffectiveDate().before(today)) {
			errorList.add(new Error("04", "EffectiveDateStart", "Please Enter Effective Date Start as Future Date"));
		}
		//Status Validation
		if (StringUtils.isBlank(req.getStatus())) {
			errorList.add(new Error("05", "Status", "Please Enter Status"));
		} else if (req.getStatus().length() > 1) {
			errorList.add(new Error("05", "Status", "Enter Status 1 Character Only"));
		}else if(!("Y".equals(req.getStatus())||"N".equals(req.getStatus()))) {
			errorList.add(new Error("05", "Status", "Enter Status Y or N Only"));
		}
		
		
		
	} catch (Exception e) {
		log.error(e);
		e.printStackTrace();
	}
	return errorList;
}
@Transactional
@Override
public SuccessRes insertRisk(RiskMasterSaveReq req) {
    SimpleDateFormat sdformat = new SimpleDateFormat("dd/MM/YYYY");
	SuccessRes res = new SuccessRes();
	RiskMaster saveData = new RiskMaster();
	List<RiskMaster> list = new ArrayList<RiskMaster>();
	 DozerBeanMapper dozerMapper = new  DozerBeanMapper();
	
	try {
		Calendar cal = new GregorianCalendar();
		cal.setTime(req.getEffectiveDate());  cal.set(Calendar.HOUR_OF_DAY, 23); cal.set(Calendar.MINUTE, 59);
		Date startDate = cal.getTime() ;
		Date today = new Date();
		cal.setTime(req.getEffectiveDate());  cal.add(Calendar.DAY_OF_MONTH, -1); cal.set(Calendar.HOUR_OF_DAY, today.getHours()); cal.set(Calendar.MINUTE, today.getMinutes());
		Date oldEndDate = cal.getTime() ;
		cal.setTime(req.getEffectiveDate());  cal.set(Calendar.HOUR_OF_DAY, today.getHours()); cal.set(Calendar.MINUTE, today.getMinutes()) ;
		Date effDate = cal.getTime();
		Date endDate = sdformat.parse("12/12/2050");
		
		
		String riskId="";
		
		if (StringUtils.isBlank(req.getRiskId().toString())) {
				// Save
			    //Long totalCount = repo.count();
				Long totalCount =getMasterTableCount();
				riskId = Long.valueOf(totalCount + 1).toString();
				saveData.setRiskId(Integer.valueOf(riskId));
				saveData.setRiskName(req.getRiskName());
				res.setResponse("Saved Successfully ");

			} else {
				// Update
				// Get Less than Equal Today Record 
				// Criteria
				riskId=req.getRiskId();
				CriteriaBuilder cb = em.getCriteriaBuilder();
				CriteriaQuery<RiskMaster> query = cb.createQuery(RiskMaster.class);

				// Find All
				Root<RiskMaster> b = query.from(RiskMaster.class);

				// Select
				query.select(b);

				// Effective Date Max Filter
				Subquery<Long> effectiveDate = query.subquery(Long.class);
				Root<RiskMaster> ocpm1 = effectiveDate.from(RiskMaster.class);
				effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
				Predicate a1 = cb.equal(ocpm1.get("riskId"), b.get("riskId"));
				Predicate a2 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart") , startDate);
				effectiveDate.where(a1,a2);

				// Order By
			//	List<Order> orderList = new ArrayList<Order>();
			//	orderList.add(cb.asc(b.get("branchName")));
				
				// Where
				Predicate n1 = cb.equal(b.get("status"), "Y");
				Predicate n2 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
				Predicate n3 =  cb.equal(b.get("riskId"), req.getRiskId() );

				query.where(n1, n2, n3);//.orderBy(orderList);

				// Get Result
				TypedQuery<RiskMaster> result = em.createQuery(query);
				list = result.getResultList();
				
				if( list.size() > 0) {
					repo.delete(list.get(0));
				} 
				res.setResponse("Updated Successfully ");

			}
		
		    dozerMapper.map(req, saveData );
			saveData.setRiskId(Integer.valueOf(riskId));
			saveData.setRiskName(req.getRiskName());
			saveData.setEffectiveDateStart(effDate);
			saveData.setEffectiveDateEnd(endDate);
			saveData.setStatus(req.getStatus());
			saveData.setEntryDate(new Date());
			repo.saveAndFlush(saveData);
			
			if(list.size() > 0 ) {
				// Update Old Record
				RiskMaster lastRecord = list.get(0) ;
				lastRecord.setEffectiveDateEnd(oldEndDate);
				repo.saveAndFlush(lastRecord);
			}
			
			log.info("Saved Details is ---> " + json.toJson(saveData));
			
} catch (Exception e) {
		e.printStackTrace();
		log.info("Exception is --->" + e.getMessage());
		return null;
	}
	return res;
}

public Long getMasterTableCount() {

	Long data = 0L;
	try {

		List<Long> list = new ArrayList<Long>();
		// Find Latest Record
		CriteriaBuilder cb = em.getCriteriaBuilder();
		CriteriaQuery<Long> query = cb.createQuery(Long.class);

		// Find All
		Root<RiskMaster> b = query.from(RiskMaster.class);

		// Select
		query.multiselect(cb.count(b));

		// Effective Date Max Filter
		Subquery<Long> effectiveDate = query.subquery(Long.class);
		Root<RiskMaster> ocpm1 = effectiveDate.from(RiskMaster.class);
		effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
		Predicate a1 = cb.equal(ocpm1.get("riskId"), b.get("riskId"));
		//Predicate a2 = cb.equal(ocpm1.get("companyId"), b.get("companyId"));
		effectiveDate.where(a1);

		Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
	
		query.where(n1);
		// Get Result
		TypedQuery<Long> result = em.createQuery(query);
		list = result.getResultList();

		data = list.get(0);

	} catch (Exception e) {
		e.printStackTrace();
		log.info(e.getMessage());

	}
	return data;
}
///*********************************************************************GET ALL******************************************************\\
@Override
public List<RiskMasterRes> getallRiskDetails(RiskMasterGetAllReq req) {
	List<RiskMasterRes> resList = new ArrayList<RiskMasterRes>();
	ModelMapper mapper = new ModelMapper();
	try {
		List<RiskMaster> riskList = new ArrayList<RiskMaster>();
		//Pagination
		int limit = StringUtils.isBlank(req.getLimit()) ? 0 : Integer.valueOf(req.getLimit());
		int offset = StringUtils.isBlank(req.getOffset()) ? 0 : Integer.valueOf(req.getOffset());

		// Find Latest Record
		CriteriaBuilder cb = em.getCriteriaBuilder();
		CriteriaQuery<RiskMaster> query = cb.createQuery(RiskMaster.class);

		// Find All
		Root<RiskMaster> b = query.from(RiskMaster.class);

		// Select
		query.select(b);

		// Effective Date Max Filter
		Subquery<Long> effectiveDate = query.subquery(Long.class);
		Root<RiskMaster> ocpm1 = effectiveDate.from(RiskMaster.class);
		effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
		Predicate a1 = cb.equal(ocpm1.get("riskId"), b.get("riskId"));
		effectiveDate.where(a1);

		// Order By
		List<Order> orderList = new ArrayList<Order>();
		orderList.add(cb.asc(b.get("riskName")));
		
		// Where
		Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);

		query.where(n1).orderBy(orderList);

		// Get Result
		TypedQuery<RiskMaster> result = em.createQuery(query);
		result.setFirstResult(limit * offset);
		result.setMaxResults(offset);
		riskList = result.getResultList();
		
		// Map
		for (RiskMaster data : riskList) {
			RiskMasterRes res = new RiskMasterRes();

			res = mapper.map(data, RiskMasterRes.class);
			mapper.getConfiguration().setAmbiguityIgnored(true);
			res.setRiskId(data.getRiskId().toString());
			resList.add(res);
		}

	} catch (Exception e) {
		e.printStackTrace();
		log.info(e.getMessage());
		return null;

	}
	return resList;
}

