@Override
public RiskMasterRes getByRiskCode(RiskMasterGetReq req) {
	RiskMasterRes res = new RiskMasterRes();
	ModelMapper mapper = new ModelMapper();
	SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");

	try {
		// Criteria
		CriteriaBuilder cb = em.getCriteriaBuilder();
		CriteriaQuery<RiskMaster> query = cb.createQuery(RiskMaster.class);
		List<RiskMaster> list = new ArrayList<RiskMaster>();
		
		// Find All
		Root<RiskMaster>    c = query.from(RiskMaster.class);		
		
		// Select
		query.select(c );
		
		// Effective Date Max Filter
		Subquery<Long> effectiveDate = query.subquery(Long.class);
		Root<RiskMaster> ocpm1 = effectiveDate.from(RiskMaster.class);
		effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
		javax.persistence.criteria.Predicate a1 = cb.equal(c.get("riskId"),ocpm1.get("riskId") );
		effectiveDate.where(a1);
		
		
		
		// Order By
		List<Order> orderList = new ArrayList<Order>();
		orderList.add(cb.asc(c.get("effectiveDateStart")));
		
	    // Where	
	
		javax.persistence.criteria.Predicate n1 = cb.equal(c.get("effectiveDateStart"), effectiveDate);		
		javax.persistence.criteria.Predicate n2 = cb.equal(c.get("riskId"),req.getRiskId()) ;


		query.where(n1 ,n2).orderBy(orderList);
		
		// Get Result
		TypedQuery<RiskMaster> result = em.createQuery(query);			
		list =  result.getResultList();  
		res = mapper.map(list.get(0) , RiskMasterRes.class);
		res.setRiskId(list.get(0).getRiskId().toString());
		res.setEntryDate(list.get(0).getEntryDate());
		res.setEffectiveDateStart(list.get(0).getEffectiveDateStart());
		res.setEffectiveDateEnd(list.get(0).getEffectiveDateEnd());
	} catch (Exception e) {
		e.printStackTrace();
		log.info("Exception is ---> " + e.getMessage());
		return null;
	}
	return res;
}

